						binaryLoader.setPath(this.libraryPath);
						binaryLoader.setResponseType("arraybuffer");
						const binaryContent = new Promise((resolve, reject) => {
							binaryLoader.load("rhino3dm.wasm", resolve, void 0, reject);
						});
